package ru.wibestyle.api.controller;
import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import ru.wibestyle.api.config.AdminProperties; import ru.wibestyle.api.domain.HairstyleCatalogEntity; import ru.wibestyle.api.repository.HairstyleCatalogRepository; import ru.wibestyle.api.storage.BlobStorage; import ru.wibestyle.api.support.AdminSupport; import java.io.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/admin/hairstyles") public class AdminHairstyleController { final HairstyleCatalogRepository repo; final BlobStorage storage; final AdminProperties admin; public AdminHairstyleController(HairstyleCatalogRepository r,BlobStorage s,AdminProperties a){repo=r;storage=s;admin=a;}
 @GetMapping public Map<String,Object> list(@RequestHeader(value="X-Admin-Key",required=false)String k){AdminSupport.requireAdminKey(k,admin);return Map.of("items",repo.findAllByOrderBySortOrderAsc().stream().map(this::map).toList());}
 @PostMapping public Map<String,Object> create(@RequestHeader(value="X-Admin-Key",required=false)String k,@RequestBody Map<String,String> b){AdminSupport.requireAdminKey(k,admin);String slug=b.get("slug"); if(slug==null||!slug.matches("[a-z0-9-]{2,80}"))throw new IllegalArgumentException("HAIRSTYLE_SLUG_INVALID"); var n=Instant.now();var e=new HairstyleCatalogEntity(UUID.randomUUID(),slug,b.getOrDefault("title",slug),b.getOrDefault("description",""),b.getOrDefault("type","medium"),b.getOrDefault("masterNote",""),b.getOrDefault("aiDirective",""),"catalog/hairstyles/"+slug+".jpg",Integer.parseInt(b.getOrDefault("sortOrder","999")),n);repo.save(e);return Map.of("item",map(e));}
 @PostMapping("/{slug}/image") public Map<String,Object> image(@RequestHeader(value="X-Admin-Key",required=false)String k,@PathVariable String slug,@RequestParam MultipartFile image)throws Exception{AdminSupport.requireAdminKey(k,admin);var e=repo.findBySlug(slug).orElseThrow(()->new IllegalArgumentException("HAIRSTYLE_NOT_FOUND"));if(image.isEmpty()||image.getSize()>10*1024*1024)throw new IllegalArgumentException("IMAGE_INVALID");String ext=image.getContentType()!=null&&image.getContentType().equals("image/webp")?".webp":".jpg";String path="catalog/hairstyles/"+slug+ext;storage.put(path,image.getInputStream());e.setImagePath(path);repo.save(e);return Map.of("item",map(e));}
 private Map<String,Object> map(HairstyleCatalogEntity s){return Map.of("id",s.getSlug(),"title",s.getTitle(),"description",s.getDescription(),"type",s.getHairType(),"masterNote",s.getMasterNote(),"aiDirective",s.getAiDirective(),"imagePath",s.getImagePath(),"sortOrder",s.getSortOrder(),"active",s.isActive());}}
